try (PreparedStatement p = c.prepareStatement("SELECT QUERY_CONTENT1,QUERY_CONTENT2,QUERY_CONTENT3,QUERY_CONTENT4,QUERY_TYPE FROM WIBAPP.WB_QUERY WHERE QUERY_ID=? AND QUERY_SERVICE='DBANK' AND DELETE_YN='N' AND APPROVAL_FLAG='A'")) {
    p.setString(1, id);
    try (ResultSet r = p.executeQuery()) {
        if (!r.next())
            throw new BankException(500, "QUERY_MISSING", "Query metadata missing: " + id);
        StringBuilder text = new StringBuilder();
        for (int i = 1; i <= 4; i++) {
            String part = r.getString(i);
            if (part != null)
                text.append(part);
        }
        if (!expectedType.equals(r.getString(5)))
            throw new BankException(500, "QUERY_TYPE", "Query type mismatch");
        sql = text.toString();
        if (r.next())
            throw new BankException(500, "QUERY_DUPLICATE", "Ambiguous Query metadata: " + id);
    }
}

