try (PreparedStatement p = c.prepareStatement("SELECT PARAM_ORDER,COLUMN_TYPE,SQL_TYPE FROM WIBAPP.WB_QUERY_PARAM WHERE QUERY_ID=? AND DELETE_YN='N' ORDER BY PARAM_ORDER")) {
    p.setString(1, id);
    try (ResultSet r = p.executeQuery()) {
        int next = 1;
        while (r.next()) {
            int position = r.getInt(1);
            String field = r.getString(2);
            if (position != next++ || !input.hasField(field))
                throw new BankException(500, "QUERY_PARAM", "Missing parameter: " + field);
            statement.setObject(position, input.getField(field), r.getInt(3));
        }
    }
    return statement;
} catch (SQLException | RuntimeException e) {
